function login() {
  try {
    var cForum = cookie.getCookie('forum.dichtienghoa.com') || cookie.getCookie('https://forum.dichtienghoa.com') || '';
    var cWiki = cookie.getCookie('wikicv.org') || cookie.getCookie('https://wikicv.org') || '';
    var all = (cForum ? cForum + '; ' : '') + (cWiki ? cWiki : '');
    if (all) {
      cookie.setCookie('wikicv.org', all);
      cookie.setCookie('https://wikicv.org', all);
      cookie.setCookie('forum.dichtienghoa.com', all);
      cookie.setCookie('https://forum.dichtienghoa.com', all);
    }
  } catch(e) {}
  return true;
}
